package com.cognizant.gateway;import org.slf4j.*;import org.springframework.cloud.gateway.filter.*;import org.springframework.core.Ordered;import org.springframework.stereotype.Component;import reactor.core.publisher.Mono;@Component public class RequestLoggingFilter implements GlobalFilter,Ordered{private static final Logger log=LoggerFactory.getLogger(RequestLoggingFilter.class);public Mono<Void>filter(org.springframework.web.server.ServerWebExchange e,GatewayFilterChain c){long t=System.currentTimeMillis();log.info("Incoming {} {}",e.getRequest().getMethod(),e.getRequest().getURI());return c.filter(e).then(Mono.fromRunnable(()->log.info("Completed {} status={} time={}ms",e.getRequest().getURI(),e.getResponse().getStatusCode(),System.currentTimeMillis()-t)));}public int getOrder(){return-1;}}